import os
import sys
from zai import ZhipuAiClient

def create_client(api_key: str = None) -> ZhipuAiClient:
    key = api_key or os.environ.get("BIGMODEL_API_KEY")
    if not key:
        raise ValueError("API key must be provided or set in the BIGMODEL_API_KEY environment variable.")
    return ZhipuAiClient(api_key=key)

def generate_chat_completion(
    client: ZhipuAiClient,
    prompt: str,
    system_prompt: str = "You are a helpful assistant.",
    model: str = "glm-5.3",
    enable_thinking: bool = True,
    temperature: float = 1.0,
    max_tokens: int = 4096
) -> str:
    messages = [
        {"role": "system", "content": system_prompt},
        {"role": "user", "content": prompt}
    ]
    params = {
        "model": model,
        "messages": messages,
        "temperature": temperature,
        "max_tokens": max_tokens
    }
    if enable_thinking:
        params["thinking"] = {"type": "enabled"}
    response = client.chat.completions.create(**params)
    return response.choices[0].message.content

def stream_chat_completion(
    client: ZhipuAiClient,
    prompt: str,
    system_prompt: str = "You are a helpful assistant.",
    model: str = "glm-5.3",
    enable_thinking: bool = True,
    temperature: float = 1.0,
    max_tokens: int = 4096
):
    messages = [
        {"role": "system", "content": system_prompt},
        {"role": "user", "content": prompt}
    ]
    params = {
        "model": model,
        "messages": messages,
        "temperature": temperature,
        "max_tokens": max_tokens,
        "stream": True
    }
    if enable_thinking:
        params["thinking"] = {"type": "enabled"}
    stream = client.chat.completions.create(**params)
    for chunk in stream:
        delta = getattr(chunk.choices[0], "delta", None)
        if delta and getattr(delta, "content", None):
            yield delta.content

if __name__ == "__main__":
    api_key = os.environ.get("BIGMODEL_API_KEY", "")
    if not api_key:
        sys.exit(1)
    client = create_client(api_key=api_key)
    result = generate_chat_completion(
        client=client,
        prompt="Explain the core features of the GLM architecture."
    )
    sys.stdout.write(result + "\n")
