import os
import sys
from typing import Generator, Optional
from openai import OpenAI

def get_client(api_key: Optional[str] = None, base_url: str = "") -> OpenAI:
    key = api_key or os.environ.get("BIGMODEL_API_KEY")
    if not key:
        raise ValueError("BIGMODEL_API_KEY environment variable is not set and no API key was provided.")
    return OpenAI(api_key=key, base_url=base_url)

def create_chat_completion(
    client: OpenAI,
    prompt: str,
    system_prompt: str = "You are a helpful AI assistant.",
    model: str = "glm-5.3",
    enable_thinking: bool = True,
    temperature: float = 1.0,
    max_tokens: int = 4096
) -> str:
    messages = [
        {"role": "system", "content": system_prompt},
        {"role": "user", "content": prompt}
    ]
    kwargs = {
        "model": model,
        "messages": messages,
        "temperature": temperature,
        "max_tokens": max_tokens
    }
    if enable_thinking:
        kwargs["extra_body"] = {"thinking": {"type": "enabled"}}
    response = client.chat.completions.create(**kwargs)
    return response.choices[0].message.content or ""

def stream_chat_completion(
    client: OpenAI,
    prompt: str,
    system_prompt: str = "You are a helpful AI assistant.",
    model: str = "glm-5.3",
    enable_thinking: bool = True,
    temperature: float = 1.0,
    max_tokens: int = 4096
) -> Generator[str, None, None]:
    messages = [
        {"role": "system", "content": system_prompt},
        {"role": "user", "content": prompt}
    ]
    kwargs = {
        "model": model,
        "messages": messages,
        "temperature": temperature,
        "max_tokens": max_tokens,
        "stream": True
    }
    if enable_thinking:
        kwargs["extra_body"] = {"thinking": {"type": "enabled"}}
    stream = client.chat.completions.create(**kwargs)
    for chunk in stream:
        if chunk.choices and chunk.choices[0].delta and chunk.choices[0].delta.content:
            yield chunk.choices[0].delta.content

if __name__ == "__main__":
    key = os.environ.get("BIGMODEL_API_KEY")
    if not key:
        sys.exit(1)
    openai_client = get_client(api_key=key)
    output = create_chat_completion(
        client=openai_client,
        prompt="Hello GLM-5.3!"
    )
    sys.stdout.write(output + "\n")
